<?php $title='Portfolio';require __DIR__.'/includes/header.php';$rows=$pdo->query("SELECT * FROM portfolio WHERE active=1 ORDER BY sort_order,id DESC")->fetchAll();?><section class="pagehead"><small>PORTFOLIO</small><h1>Hasil produksi Animo Label</h1></section><section class="section"><div class="portfolio-grid"><?php foreach($rows as $r):?><figure><img src="<?=e(img($r['image']))?>"><figcaption><b><?=e($r['title'])?></b><span><?=e($r['description'])?></span></figcaption></figure><?php endforeach;?></div></section><?php require __DIR__.'/includes/footer.php';?>